\set ON_ERROR_STOP on
-- Disposable localhost database only. Auth + pre-002 tables are synthetic.
create schema auth;
create table auth.users(id uuid primary key);
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claim.sub',true),'')::uuid$$;
create function auth.jwt() returns jsonb language sql stable as $$select coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb$$;
grant usage on schema auth to anon,authenticated;
grant execute on all functions in schema auth to anon,authenticated;
create table public.modara_units(unit_id text primary key,label text,status text,timezone text);
insert into public.modara_units values('plus54-jardim-aquarius','Synthetic +54','active','America/Sao_Paulo'),('quintal-skatepark','Synthetic FAST','active','America/Sao_Paulo');
create table public.modara_admin_users(user_id uuid primary key references auth.users);
create table public.table_sessions(id bigint generated by default as identity primary key,unit_id text not null,table_num integer,status text default 'active',party_size integer,created_at timestamptz default now(),updated_at timestamptz default now(),closed_at timestamptz);
create table public.customer_sessions(id bigint generated by default as identity primary key,table_session_id bigint references public.table_sessions,name text,display_name text,phone text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.orders(id bigint generated by default as identity primary key,table_session_id bigint references public.table_sessions,customer_session_id bigint references public.customer_sessions,status text default 'pending',items jsonb default '[]',created_at timestamptz default now(),total numeric default 0);
create table public.order_station_executions(id bigint generated by default as identity primary key,order_id bigint references public.orders,production_station text,status text default 'pending',production_mode text default 'preparation',created_at timestamptz default now(),started_at timestamptz,ready_at timestamptz,delivered_at timestamptz);
-- Operational dependency stubs are NEVER used to claim production/delivery tests.
create function public.patch_027a_guard_station_execution() returns trigger language plpgsql as $$begin return new; end$$;
create function public.confirm_station_execution_delivery(bigint) returns public.order_station_executions language plpgsql as $$begin raise exception 'synthetic delivery must not run'; end$$;
